const evt=$input.first().json?.raw_data||$input.first().json;
const caseId=`DFIR-${Date.now()}`;
const hosts=Array.isArray(evt.affected_hosts)?evt.affected_hosts:[evt.hostname||evt.host||'unknown'];
return[{json:{case_id:caseId,incident_id:evt.incident_id||caseId,hosts,severity:evt.severity||'High',
  declared_by:evt.declared_by||'system',declared_at:new Date().toISOString(),
  evidence_bucket:`s3://constellation-evidence/${caseId}/`,
  legal_hold:evt.legal_hold||false}}];

const c=$input.first().json;
// Define collection tasks per host
const tasks=c.hosts.flatMap(host=>[
  {host,task:'collect_system_logs',files:['/var/log/syslog','/var/log/auth.log','/var/log/messages'],priority:1},
  {host,task:'collect_process_list',command:'ps auxf',priority:1},
  {host,task:'collect_network_state',command:'netstat -antp',priority:1},
  {host,task:'collect_open_files',command:'lsof -n',priority:2},
  {host,task:'collect_cron_jobs',files:['/etc/cron*','/var/spool/cron'],priority:2},
  {host,task:'collect_bash_history',files:['/root/.bash_history','~/.bash_history'],priority:1}
]);
// Calculate evidence hash (in production: SHA-256 each file, store manifest)
const evidence_manifest={case_id:c.case_id,collection_time:new Date().toISOString(),
  tasks_planned:tasks.length,hosts:c.hosts,collector:'Constellation DFIR-01'};
return[{json:{...c,tasks,tasks_count:tasks.length,evidence_manifest}}];

